{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/feature-split.json
    Features beside a picture. Axes: layout (grid: four plain features in two columns, cards: four features as cards and the actions, stats: two figure cards over three checked rows beside a square picture, metrics: four metric cards and the actions), mediaSide, tone.
    Props (p): id, title, lead, badge, level, features, stats, actions, layout, mediaSide, tone, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_badge = ($p['badge'] ?? '')}
{var $v_level = ($p['level'] ?? 2)}
{var $v_features = ($p['features'] ?? null)}
{var $v_stats = ($p['stats'] ?? null)}
{var $v_actions = ($p['actions'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'grid')}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_1}
  {=og_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => (og_t(og_eq($v_layout, 'stats')) ? '1/1' : '4/3')]])|noescape}
{/capture}
{capture $c_2}
  {if og_t(og_eq($v_layout, 'grid'))}
    {if og_t(og_gt(og_len($v_features), 0))}
      {=og_include('blocks/feature-pairs.latte', ['p' => ['features' => $v_features]])|noescape}
    {/if}
  {/if}
  {if og_t(og_eq($v_layout, 'cards'))}
    {if og_t(og_gt(og_len($v_features), 0))}
      {=og_include('blocks/feature-cards.latte', ['p' => ['features' => $v_features, 'cols' => '1-2', 'item' => 'tile']])|noescape}
    {/if}
  {/if}
  {if og_t(og_eq($v_layout, 'stats'))}
    {if og_t(og_gt(og_len($v_features), 0))}
      {=og_include('blocks/feature-stat-rows.latte', ['p' => ['features' => $v_features, 'stats' => $v_stats]])|noescape}
    {/if}
  {/if}
  {if og_t(og_eq($v_layout, 'metrics'))}
    {if og_t(og_gt(og_len($v_stats), 0))}
      {=og_include('blocks/feature-metric-cards.latte', ['p' => ['stats' => $v_stats]])|noescape}
    {/if}
  {/if}
  {if og_t(og_or([og_eq($v_layout, 'cards'), og_eq($v_layout, 'metrics')]))}
    {=og_include('blocks/action-group.latte', ['p' => ['primary' => og_get($v_actions, ['cta']), 'primaryHref' => og_get($v_actions, ['href']), 'secondary' => (og_t(og_eq(og_get($v_actions, ['mode']), 'two')) ? og_get($v_actions, ['secondary']) : null), 'secondaryHref' => og_get($v_actions, ['secondaryHref'])]])|noescape}
  {/if}
{/capture}
{=og_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'heading' => ['badge' => $v_badge, 'level' => $v_level], 'tone' => $v_tone, 'layout' => 'split', 'media' => ['show' => true, 'side' => $v_mediaSide], 'landmarkLabel' => $v_landmarkLabel, 'aside' => og_markup($f_1)], 'children' => og_markup($c_2)])|noescape}
